// ── KMP: Build Failure Function — O(m) ────────────────────────
function buildLPS(pattern) {
  const m = pattern.length;
  const lps = new Array(m).fill(0);
  let len = 0; // length of previous longest prefix-suffix
  let i = 1;

  while (i < m) {
    if (pattern[i] === pattern[len]) {
      lps[i] = ++len;
      i++;
    } else if (len > 0) {
      len = lps[len - 1]; // don't increment i
    } else {
      lps[i] = 0;
      i++;
    }
  }
  return lps;
}

// ── KMP Search — O(n) ─────────────────────────────────────────
function kmpSearch(text, pattern) {
  const n = text.length, m = pattern.length;
  const lps = buildLPS(pattern);
  const matches = [];
  let i = 0; // text index
  let j = 0; // pattern index

  while (i < n) {
    if (text[i] === pattern[j]) {
      i++; j++;
    }
    if (j === m) {
      matches.push(i - j); // match found at this index
      j = lps[j - 1];      // look for next match
    } else if (i < n && text[i] !== pattern[j]) {
      if (j > 0) j = lps[j - 1]; // use failure function
      else i++;                    // no prefix to fall back to
    }
  }
  return matches;
}

const text = "ABABDABACDABABCABAB";
const pattern = "ABABCABAB";
console.log(kmpSearch(text, pattern)); // [10]
// Pattern found starting at index 10

// Failure function example:
const lps = buildLPS("ABABCABAB");
console.log(lps); // [0,0,1,2,0,1,2,3,4]
// lps[7]=3 means 'ABABCABA' has a prefix-suffix of length 3 ('ABA')

// ── Rabin-Karp Rolling Hash — O(n+m) expected ─────────────────
function rabinKarp(text, pattern) {
  const n = text.length, m = pattern.length;
  const BASE = 31;
  const MOD = 1_000_000_007;
  const matches = [];

  if (m > n) return matches;

  // Compute BASE^(m-1) mod MOD
  let highPow = 1;
  for (let i = 0; i < m - 1; i++) highPow = (highPow * BASE) % MOD;

  // Helper: char to number
  const code = c => c.charCodeAt(0) - 96; // 'a'=1 ... 'z'=26

  // Compute initial hashes
  let patHash = 0, winHash = 0;
  for (let i = 0; i < m; i++) {
    patHash = (patHash * BASE + code(pattern[i])) % MOD;
    winHash = (winHash * BASE + code(text[i])) % MOD;
  }

  for (let i = 0; i <= n - m; i++) {
    if (winHash === patHash) {
      // Hash match: verify with direct comparison (avoid false positives)
      if (text.slice(i, i + m) === pattern) {
        matches.push(i);
      }
    }
    // Roll the hash: remove text[i], add text[i+m]
    if (i < n - m) {
      winHash = (winHash - code(text[i]) * highPow % MOD + MOD) % MOD;
      winHash = (winHash * BASE + code(text[i + m])) % MOD;
    }
  }
  return matches;
}

console.log(rabinKarp("abcababcabc", "abc")); // [0, 5, 8]

// ── Naive String Search — O(n*m) for reference ─────────────────
function naiveSearch(text, pattern) {
  const matches = [];
  for (let i = 0; i <= text.length - pattern.length; i++) {
    let j = 0;
    while (j < pattern.length && text[i + j] === pattern[j]) j++;
    if (j === pattern.length) matches.push(i);
  }
  return matches;
}
